// ❌ OLD: A repr(Rust) struct (the default) gives the compiler freedom
// to REORDER fields. Here x: u8, y: u64, z: u8 — the default layout
// will likely place x, z, then y (to avoid the 7-byte gap after each
// u8 before the u64), so the in-memory offsets are NOT x@0,y@8,z@16.
// If you pass this struct to C (or read it from a binary format)
// assuming declaration order, you get garbage.
#[repr(C)] // <-- missing → wrong assumption
struct Point {
    x: u8,
    y: u64,
    z: u8,
}

// size_of::<Point>() under default layout: 16 (x,z packed, then y).
// Under #[repr(C)]: 24 (x@0, pad to 8, y@8, z@16, pad to 24).
// Passing the default-layout struct to C that expects the repr(C)
// layout corrupts the data.

// ✅ NEW: #[repr(C)] fixes the layout to C's rules: fields in
// declaration order, each aligned to its type, trailing padding to the
// struct alignment. This is the layout a C struct with the same
// members would have, so FFI works.
#[repr(C)] // ✅ NEW: FFI-safe layout
struct Point {
    x: u8,
    y: u64,
    z: u8,
}

// size_of::<Point>() == 24 (x@0, 7 bytes padding, y@8, z@16,
// 7 bytes trailing padding to align 8).

